create() {
  if (this.inputGuardMs > 0) {
    this.input.enabled = false;

    const tryEnable = () => {
      if (!this.scene.isActive()) return;
      // 손가락이 아직 닿아 있으면 50ms 뒤 재시도 — 뗄 때까지 input 재활성화 연기
      const anyDown = this.input.manager.pointers.some((p: Phaser.Input.Pointer) => p.isDown);
      if (anyDown) {
        this.time.delayedCall(50, tryEnable);
      } else {
        this.input.enabled = true;
      }
    };

    this.time.delayedCall(this.inputGuardMs, tryEnable);
  }
}

